INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (26, 'source_value_extractions', 'claim_text', '101', '5722908582c15fa92a56a02f24cd431df8740a366fdf857cac7e97347a3a38d9', 'EN', 'Ramps of less than 3 m: maximum slope 10%. Ramps of between 3 and 10 m: maximum slope 8%.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (27, 'source_value_extractions', 'claim_text', '102', '7c6938f5f59c77e5fa4d3ec455e04d7ebb112876e890ef8f0b048f6acef1bc24', 'EN', 'slopes above 6% (the limit the law sets) begin to cause significant problems for many people to travel along, and from 10% they are impracticable.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (28, 'source_value_extractions', 'claim_text', '103', '9d4f70eb79fba6a4dafc87a29236e91a03ea95ef2fef4f56b81ad4e478d4bc24', 'EN', 'Where a level difference cannot be avoided, an inclined plane with a slope of 6% or less is provided to cross it. The following slope values are tolerated exceptionally: up to 10% over a length of 2 m or less; up to 12% over a length of 0.50 m or less.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (29, 'source_value_extractions', 'claim_text', '104', 'da7ab5b48e21a3dd1a87ec9172ac91f4e26f6d4dc2296d334ad7b66fb00445d2', 'EN', 'From 6% over several metres, a large number of people in manual wheelchairs will lose their independence and have to ask for help. Many other people with reduced mobility will suffer comparable difficulty.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (30, 'source_value_extractions', 'claim_text', '105', '57930ff6487a3ed3f1b2b20762fc3f283c138e2a7b3d27767f4331ee111b7ad5', 'EN', 'an inclined plane with a slope of 5% or less will be preferred', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (31, 'source_value_extractions', 'claim_text', '106', '32fbdac3915d4bc5d3c71453ce8dafc086799cd388e2ffd101350f8d3e8c8bf9', 'EN', 'The added dimensions of the ramp are taken from NEN 9120, which is under development, «Dutch elaboration of NEN-EN 17210 Performance requirements for accessibility and usability of buildings».', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (32, 'source_value_extractions', 'claim_text', '107', 'ee56d285a892b552b94124d0bc54f7ada56739938ae6b64aaff079fd1d1d600f', 'EN', 'The gradient of a ramp shall be 1/12 or less.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (33, 'source_value_extractions', 'claim_text', '108', '8e30d3c7cbc8e7016ac8d582359692c25c38085b8d27d29843e818da1c929545', 'EN', 'Where all of the following requirements are met, the gradient of a ramp may be relaxed up to 1/8. (a) The ramp is installed in an existing facility, not new construction; (b) it is a ramp with a height of 1 metre or less, for which installing a gradient of 1/12 or less is difficult for reasons such as the structure of the facility; (c) a permanent assistance service is provided by the facility manager or similar.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (34, 'source_value_extractions', 'claim_text', '109', '8406af6837a35452cece01c691c66fdae48bab0956383bcf6b9dfb07d22495ab', 'EN', '1) Have a slope not exceeding 6%, overcome a level difference not exceeding 0.6 m and have a horizontal projection not exceeding 10 m;', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (35, 'source_value_extractions', 'claim_text', '110', '9aaf607e821edebb6cf26ea53354161919b18a5de3b981fc6d2f67508aab1870', 'EN', '2) Have a slope not exceeding 8%, overcome a level difference not exceeding 0.4 m and have a horizontal projection not exceeding 5 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (36, 'source_value_extractions', 'claim_text', '111', '4a2c92b80b5e0ac54a4b39d171b0507d2912df7cb9fd61b72eccac65b8f1735e', 'EN', 'In the case of buildings undergoing alteration or conservation works, if space limitations prevent the use of ramps with a slope not exceeding 8%, the ramps may have steeper slopes if they satisfy one of the following situations, or values interpolated from those indicated: 1) Have a slope not exceeding 10%, overcome a level difference not exceeding 0.2 m and have a horizontal projection not exceeding 2 m; 2) Have a slope not exceeding 12%, overcome a level difference not exceeding 0.1 m and have a horizontal projection not exceeding 0.83 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (37, 'source_value_extractions', 'claim_text', '112', '02951e6d82a8e816d63dc66b0b7a3b11b4f127dc6a5e570dbce81027bf6323e6', 'EN', 'The requirements for ramps are being adjusted so that they are in line with the NEN standard 9120, which is under development. Ieder(in) supports the implementation of this NEN standard', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (38, 'source_value_extractions', 'claim_text', '113', '3dfaed65bb9da5a80181897b746a4f758557e9b8cdb036f6381a4322ad21e7be', 'EN', 'A ramp should a) slope at most 1:20 between landings at least 2 metres long, b) have a level difference of at most 0.5 metres between the landings', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (39, 'source_value_extractions', 'claim_text', '114', '47f3dce5b2b37151cce073af6d514dcd455df67f513f70e23bc2c54930bcec07', 'EN', 'A levelling to 0-level should not have a greater slope than 1:12. The width should be 90–100 cm.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (40, 'source_value_extractions', 'claim_text', '115', 'bf6350c67b9a54b6dea2d046d7be30bdd9fac65105df4472557013a2a74b2379', 'EN', 'The provision applies only to access paths with a slope greater than 4%', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (41, 'source_value_extractions', 'claim_text', '116', 'aa4a38aba426eab377bbf5dcb97a8a3ec4405af74e8b116c880d106c90064cc7', 'EN', 'Ramp flights may have a length of at most 600 cm.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (42, 'source_value_extractions', 'claim_text', '118', '4a570f8aee470bb23d22e5534aedbbf833b07d40f3687b58f056a00c239e5571', 'EN', 'Where a level difference of more than 50 cm is bridged, or a slope of more than 10 m with a gradient of more than four per cent, an intermediate landing of 120 cm by 150 cm must be provided.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (43, 'source_value_extractions', 'claim_text', '128', 'ba3632d7d73383b7caf1641de423370d7e16c236861b7273a638dd098fb9ab1b', 'EN', 'In the case of an inclined plane with a slope of 5% or more, a rest landing is required every 10 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (44, 'source_value_extractions', 'claim_text', '129', 'cac5533cf7f451465600cc6c9659ae60086827224697da0c9cf19155b3cd10fd', 'EN', 'It is recommended to provide a rest landing every 10 m as soon as a slope above 2% is built over a long distance, without waiting for the regulatory threshold of 5%', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (45, 'source_value_extractions', 'claim_text', '141', '1794446371456e373491a709a85e03e0b1072db78fdfdc93b22b100791880ff2', 'EN', 'The sections shall have a length of 15 m at most, except where the ramp belongs to accessible routes, in which case the length of the section shall be 9 m at most', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (46, 'source_value_extractions', 'claim_text', '142', '4969bd64279be00fc33fd0bc5e24de2adb9ff59c546b118cdaaeadfe02008a8e', 'EN', 'The maximum longitudinal slope shall be 10% for sections up to 3.00 m long, and 8% for sections up to 9.00 m long, measured in horizontal projection.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (47, 'source_value_extractions', 'claim_text', '143', '3157572c5685b72ded3f49591ae612a581b66e2ce691ffbe1d3563893ee35899', 'EN', 'Have a slope not exceeding 6%, overcome a level difference not exceeding 0.6 m and have a horizontal projection not exceeding 10 m', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (48, 'source_value_extractions', 'claim_text', '144', '902de35a42c70b996fc34e2d367c174344c37af268e382b7986e95eb06ff2bbb', 'EN', 'Have a slope not exceeding 8%, overcome a level difference not exceeding 0.4 m and have a horizontal projection not exceeding 5 m', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (49, 'source_value_extractions', 'claim_text', '145', 'ba3632d7d73383b7caf1641de423370d7e16c236861b7273a638dd098fb9ab1b', 'EN', 'In the case of an inclined plane with a slope of 5% or more, a rest landing is required every 10 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (50, 'source_value_extractions', 'claim_text', '146', 'cac5533cf7f451465600cc6c9659ae60086827224697da0c9cf19155b3cd10fd', 'EN', 'It is recommended to provide a rest landing every 10 m as soon as a slope above 2% is built over a long distance, without waiting for the regulatory threshold of 5%', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (51, 'source_value_extractions', 'claim_text', '19', '4c58bc22cd212ec329e842d284c2b7ae99640eb098fa5d72e35cf863bc1092a6', 'EN', 'Ramp flights may have a gradient of at most 6%; this is also felt to be comfortable by pedestrians.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (52, 'source_value_extractions', 'claim_text', '198', 'ebbf78e3024bcf4e7c8d405276f85d47f473dda9eef814363c932f9cd3399bcc', 'EN', 'Along its whole length it shall have a clear passage width of not less than 1.80 m, which ensures that people can turn, pass one another and change direction, whatever their characteristics or mode of movement.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (53, 'source_value_extractions', 'claim_text', '199', 'bfeb20b741abee9c27a7ae7945a6ad914755e8d20f77d3d8668eee7c3a010c20', 'EN', 'Along its whole length it shall have a clear passage height of not less than 2.20 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (54, 'source_value_extractions', 'claim_text', '20', 'a4f0d7a8f4f2bf97d1697379f2c6f83cb015e301a748a98a872575eafb1ba076', 'EN', 'In practice, for an ordinary wheelchair user who is used to riding, I think 1/12 is fine. At 1/8, I think it can be done with a run-up.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (55, 'source_value_extractions', 'claim_text', '200', 'ff2b4e795d74c94bc6c3b659890a68714f18b9ac5e179cd8ed65522e57556ad6', 'EN', 'They shall have a space free of obstacles in which a circle of 1.50 m diameter, at least, can be inscribed, in front of the access door, and that space may coincide neither with the accessible pedestrian route nor with the area swept by the opening of the cabin door.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (56, 'source_value_extractions', 'claim_text', '201', 'e9e03872420884f1eaeaaac5deaace03e728f3bef837b7c0c9d5d8e8a48b6958', 'EN', 'Beside the door there shall be a space free of obstacles that allows a circle of 1.50 m minimum diameter to be inscribed over its whole height, the minimum height inside the cabin being 2.20 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (57, 'source_value_extractions', 'claim_text', '202', '6775944cc0abc691219f783f1b801af571ac521fb89542c5fc492624c1da1d29', 'EN', 'the minimum height inside the cabin being 2.20 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (58, 'source_value_extractions', 'claim_text', '203', 'f7fc805251e2f45f960ccbc52cbd3b363b6cdda2dc89c6bc6cf07986a833cc7c', 'EN', 'The access door shall open outwards or be sliding, shall have a minimum clear passage width of 80 cm, and its closing mechanism shall be easy to operate, allowing it to be opened from outside in an emergency.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (59, 'source_value_extractions', 'claim_text', '204', '893e63ae880be5db5968010c5f49f2c201e65b01040a518a547de5dcb7beb7af', 'EN', 'In any case the opening mechanism shall not require a force greater than 25 N and the closing system shall be delayed.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (60, 'source_value_extractions', 'claim_text', '205', '30b9688fdccce29ee87f092170dd76b5b99d42de2dfbb6e15675880f7e20a834', 'EN', 'The operating mechanisms of washbasins, showers and toilet flushing mechanisms shall be large-surface push buttons operable with the fist or the elbow, or easy-to-use levers, and shall require little effort.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (61, 'source_value_extractions', 'claim_text', '206', '9039222900bfaab3b80973e74058ba7fd1ca1b2a878b459e315274e4479ad2c2', 'EN', 'All vertical or horizontal posts that delimit the route shall be covered with materials that protect against impacts, and their visibility shall be ensured by means of high-contrast colours.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (62, 'source_value_extractions', 'claim_text', '207', '82f2d0068f9dfdf28a85144db49344d58fb1e03ca16a953d0dfbf71d00eabf1f', 'EN', 'The entrance (door) shall have a clear passage width of 0.9 metres or more, as in the figure below, and', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (63, 'source_value_extractions', 'claim_text', '208', 'ba55486c3377074a665f4a2648b015db429b3cee1d82dd73719388a2209b7865', 'EN', 'The clear width of a corridor shall be 1.2 metres or more, but', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (64, 'source_value_extractions', 'claim_text', '209', 'cd2c7e757cec1b7e42650a91035c0793a0d4dca1226003753fd4f49b2521f578', 'EN', 'may be 1.5 metres or more.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (65, 'source_value_extractions', 'claim_text', '21', '4b4575b3ae0ee0f5337db978ab8cece31e1c19a0a51b42d76b4f756957c5c909', 'EN', 'Where the gradient is steeper than 1/8, however much of a slope there is, going up it in a self-propelled wheelchair is close to impossible.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (66, 'source_value_extractions', 'claim_text', '210', 'b4d652bb862524790252208dfe7ec4c031d447fcbc15efc5c890ee28e3aba36a', 'EN', 'Above the passage, a clear height of 2.1 metres or more from the floor surface shall be secured.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (67, 'source_value_extractions', 'claim_text', '211', '319162565bd389e2fa522e1d858618a20fcbba9f310b20b6994ca0c5f3ab5c19', 'EN', 'In this case, an activity space of 1.4 metres × 1.4 metres or more shall be secured in front of the toilet so that a wheelchair can turn.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (68, 'source_value_extractions', 'claim_text', '212', 'b3f75f7c7c04b3ece37562297ea5629f945de8d8992bbd019b7bf9c7c00ddf17', 'EN', 'The entrance/exit doors of buildings and establishments shall have a clear width of not less than 0.87 m', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (69, 'source_value_extractions', 'claim_text', '213', 'bfaf1de76d73bdf674551fa3e2157b0f917fa9f1a51dde5c3a14673185763970', 'EN', 'Landings, galleries and corridors shall have a width of not less than 1.2 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (70, 'source_value_extractions', 'claim_text', '214', 'a131a3e54f2be7fdf11a43fb292368964ea508ae0a33ada742ac8e502944d28e', 'EN', 'There may be stretches of landings, galleries or corridors with a width of not less than 0.9 m, if their length is less than 1.5 m and if they do not give access to side doors of accessible spaces.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
