INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (79, 'source_value_extractions', 'claim_text', '227', '0e2ece8b8de989b42950b6e88b63b2f1a70fd1967831cf80b3acb8349b371881', 'EN', 'Ramps shall have a width of not less than 1.2 m, except in the following situations:', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (80, 'source_value_extractions', 'claim_text', '23', 'a63742cad9f9ebb13d584e59b44d249fd482071b474fe43c0987fceef1e40356', 'EN', 'However, for one with a height of 16 centimetres or less, it shall not exceed 1/8.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (81, 'source_value_extractions', 'claim_text', '24', '4cb4c158849519ab7ac66c830b77cfb0f6dadaf45f851cabb2eee9036fec5991', 'EN', 'The gradient shall not exceed 1/15.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (82, 'source_value_extractions', 'claim_text', '27', '77e309d66c6dbaf0bc4bc84c40c034b344b98d1253240000d2da9062719b899f', 'EN', 'Compared with the barrier-free design standard drawn up by the International Paralympic Committee, the "IPC Accessibility Guide", the mandatory standards of the Barrier-Free Act are low, especially for buildings, and the Smooth Movement Standards (mandatory standards) alone do not allow smooth use.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (83, 'source_value_extractions', 'claim_text', '30', 'a8f7d7565f444944ad654bbfe2cfa6b3a975ec14786f67843a734a6994a1c304', 'EN', 'five per cent for level differences of 50 cm or greater', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (84, 'source_value_extractions', 'claim_text', '31', '8f2cf64a759267d0be5c562597a43be506d84a9ae13260077c8ff7905c222ec9', 'EN', 'For ramps, the physical feasibility for the (independent) wheelchair user is the starting point.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (85, 'source_value_extractions', 'claim_text', '32', 'bbb034dd628843af84875846b9fababc0722f978fcae7a206b5d827b24b3ddb7', 'EN', 'The greater the height difference, the gentler (smaller gradient percentage) the ramp must be, because one has to exert effort for a longer time, and so it must remain feasible for everyone to take the whole ramp.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (86, 'source_value_extractions', 'claim_text', '72', '1bf81c2ece935c75290ba47e162bb1a06a330483c69d3333ab23148050d2a4c9', 'EN', 'As a result, of the 90 buildings assessed, only 47.8% have an access ramp; of these, 30.0% have the maximum slope and 32.2% have non-slip flooring.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (87, 'source_value_extractions', 'claim_text', '73', '1bf81c2ece935c75290ba47e162bb1a06a330483c69d3333ab23148050d2a4c9', 'EN', 'As a result, of the 90 buildings assessed, only 47.8% have an access ramp; of these, 30.0% have the maximum slope and 32.2% have non-slip flooring.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (88, 'source_value_extractions', 'claim_text', '74', 'ecef7f35671ebc08ac8e7659e23ad61f58660d7abe88b4cdd9cc3e6400b7f359', 'EN', 'A ramp shall have an even, slip-resistant surface and a gradient of at most 1:15. For stretches under 3.0 m the gradient may be at most 1:12.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (89, 'source_value_extractions', 'claim_text', '80', '7e0ef9d83594f302d7b43e97a08b20dd07cb9fa1ad0d81fccb085914ea349edf', 'EN', 'The gradient of a ramp may be at most five per cent. If the height difference is at most 1 000 millimetres, the gradient of the ramp may however be at most eight per cent.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (90, 'source_value_extractions', 'claim_text', '82', 'ee56d285a892b552b94124d0bc54f7ada56739938ae6b64aaff079fd1d1d600f', 'EN', 'The gradient of a ramp shall be 1/12 or less.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (91, 'source_value_extractions', 'claim_text', '83', '8e30d3c7cbc8e7016ac8d582359692c25c38085b8d27d29843e818da1c929545', 'EN', 'Where all of the following requirements are met, the gradient of a ramp may be relaxed up to 1/8. (a) The ramp is installed in an existing facility, not new construction; (b) it is a ramp with a height of 1 metre or less, for which installing a gradient of 1/12 or less is difficult for reasons such as the structure of the facility; (c) a permanent assistance service is provided by the facility manager or similar.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
