INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (97, 'source_value_extractions', 'claim_text', '90', '1db33e41d4ec100b48832ba132e7543ddfdc8daef735e19580619e272a51f6e0', 'EN', 'A ramp that is there to meet the requirements under section 1 and section 2, second paragraph, shall slope at most 1:12.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (98, 'source_value_extractions', 'claim_text', '93', '9dc0174642c79960198a05c58765b1a5ceec23fa79e280bf3d462bf745a5611d', 'EN', 'A ramp slope of 1:12 is a safety risk. It requires strength in the arms and great manoeuvring skill to keep the wheelchair from rolling backwards and tipping over.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (99, 'source_value_extractions', 'claim_text', '94', '9d3bcedf6a94c222a3c61739aa005f4e70705283d933c18cbde30709742cb00a', 'EN', 'Since the premise of the regulations is that a person should be able to move about independently, we consider it absolutely necessary that the slope 1:20 be introduced as the standard. We demand that the maximum permitted ramp slope be stated as 1:20. If this cannot be achieved, a lifting device is required.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (100, 'source_value_extractions', 'claim_text', '95', '4b4c6f88cb9cd24017ba23924015a846682f1ca89fa8e66e1ade88ec98555be1', 'EN', '1) Have a slope not exceeding 6%, overcome a level difference not exceeding 0.6 m and have a horizontal projection not exceeding 10 m;', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (101, 'source_value_extractions', 'claim_text', '96', '4dbd41b242599a52fbd5489509cd751a4a280a41b3237128a777ff770629a768', 'EN', '2) Have a slope not exceeding 8%, overcome a level difference not exceeding 0.4 m and have a horizontal projection not exceeding 5 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (102, 'source_value_extractions', 'claim_text', '97', '4a2c92b80b5e0ac54a4b39d171b0507d2912df7cb9fd61b72eccac65b8f1735e', 'EN', 'In the case of buildings undergoing alteration or conservation works, if space limitations prevent the use of ramps with a slope not exceeding 8%, the ramps may have steeper slopes if they satisfy one of the following situations, or values interpolated from those indicated: 1) Have a slope not exceeding 10%, overcome a level difference not exceeding 0.2 m and have a horizontal projection not exceeding 2 m; 2) Have a slope not exceeding 12%, overcome a level difference not exceeding 0.1 m and have a horizontal projection not exceeding 0.83 m.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (103, 'source_value_extractions', 'claim_text', '98', '7bf06fb2dfd82f51408720a0ba0af035d72c640481fb04eb10fc05257aea4de7', 'EN', 'Ramps shall have a slope of 12% at most, except:', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (104, 'source_value_extractions', 'claim_text', '99', 'cfdb10f4ac1b4f24b29a02220e2241a031b191955e57f94e90ae9c833111671e', 'EN', 'those belonging to accessible routes, whose slope shall be at most 10% when their length is less than 3 m, 8% when the length is less than 6 m, and 6% in the remaining cases.', 'translated', 'model', 'claude-opus-5-5', 'judgment', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-20 06:27', 'session_2026-11-20-core-work', '2026-11-20 06:27', 'session_2026-11-20-core-work');
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-368', 'SW', 'P2', 'OPEN', 'run-pipeline', NULL, 'English renderings sit in claimed_value and claimed_unit of figures from non-English sources, which the owner''s 2026-11-20 statement (ACTION 2: an English rendering is not written into claimed_value or claimed_unit) forbids. The real translations of these figures'' claim_text are now in translations (session_2026-11-20-core-work), so the cells can be cleaned, but no verb can: amend-extraction refuses a blank and permits a reformat with the same numbers only, and the table CHECK (claim_type <> ''absent'' AND claimed_value IS NOT NULL) forbids emptying claimed_value on a qualitative figure. Derive the cells: prose in claimed_value, python3 -c over source_value_extractions joined to evidence_sources where upper(coalesce(lang_detected,language,''EN''))<>''EN'' and claimed_value matches two words of three letters or more (extraction_ids 20 21 27 31 32 80 93 102 104 106 112 on 2026-11-20); a sentence in claimed_unit, same join where claimed_unit contains whitespace. Needs a writer (and a decision on what a qualitative figure''s claimed_value holds) before cleanup.', '2026-11-20 06:28', 'session_2026-11-20-core-work', '2026-11-20 06:28', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-369', 'SW', 'P2', 'OPEN', 'run-pipeline', NULL, 'evidence_sources.lang_detected is NULL on 8 sources (select ref_id from evidence_sources where lang_detected is null and language is null), so translations --due-at judgment treats them as English and owes nothing for them. Their titles read as English, but the language is a recorded fact and no verb can set it after admission: lang_detected is neither in amend-source''s _AMENDABLE nor in correct-source''s payload fields. Needs a writer (amend-source --field lang_detected through _check_language) and then the 8 values.', '2026-11-20 06:28', 'session_2026-11-20-core-work', '2026-11-20 06:28', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-370', 'SW', 'P2', 'OPEN', 'run-pipeline', NULL, 'Units outside base_units on numerical and range figures cannot be added (B, owner 2026-11-20 ''convert units''): base_units is not in dbcore.writable_tables and no add-unit verb exists, so N (operating force), points (LRV contrast) and the bare ratio (ramp gradient, T-086) stay unconvertible. Derive: select claimed_unit,count(*) from source_value_extractions where retired_at is null and claim_type in (''numerical'',''range'') and claimed_unit not in (select unit from base_units) group by 1. Needs the T-137 unit verb (tooling), then the rows.', '2026-11-20 06:28', 'session_2026-11-20-core-work', '2026-11-20 06:28', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-371', 'SW', 'P3', 'OPEN', 'run-pipeline', NULL, 'REF-00994''s pub_title ''IPC Accessibility Guide, 4th edition'' is composed from the publisher''s file name; the retrieved PDF''s cover reads ''Accessibility Guide'', ''October 2020'', International Paralympic Committee (page render retrieval-log/session_2026-11-20-core-work/b1e81d4770d19d9b.p0000.png), and ''edition'' occurs nowhere in its text extraction. author_fidelity (retrieval_log.py --verify-authors --all-sessions) is red on it for that reason alone. correct-source writes a title only from a JSON payload and amend-source refuses bibliographic fields, so no verb can correct a title read from a page; needs a writer that takes the title from a logged transcription, or an owner decision that the composed title stands.', '2026-11-20 06:28', 'session_2026-11-20-core-work', '2026-11-20 06:28', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);